DROP TABLE IF EXISTS `lt_num4_type`;
CREATE TABLE `lt_num4_type` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `code` varchar(8) DEFAULT NULL COMMENT '彩种',
  `code_1` varchar(1) DEFAULT NULL,
  `code_2` varchar(1) DEFAULT NULL,
  `code_3` varchar(1) DEFAULT NULL,
  `code_4` varchar(1) DEFAULT NULL,
  `type_2` tinyint(1) DEFAULT '0' COMMENT '是否双重',
  `type_22` tinyint(1) DEFAULT '0' COMMENT '是否双双重',
  `type_3` tinyint(1) DEFAULT '0' COMMENT '是否三重',
  `type_4` tinyint(1) DEFAULT '0' COMMENT '是否四重',
  `type_2b` tinyint(1) DEFAULT '0' COMMENT '是否两兄弟',
  `type_3b` tinyint(1) DEFAULT '0' COMMENT '是否三兄弟',
  `type_4b` tinyint(1) DEFAULT '0' COMMENT '是否四兄弟',
  `type_4ds` tinyint(1) DEFAULT '0' COMMENT '单双：0非四单四双1四单2四双',
  `type_log` tinyint(1) DEFAULT '0' COMMENT '是否对数',
  `type_3n_2b` tinyint(1) DEFAULT '0' COMMENT '三现:双重+兄弟',
  `type_3d` tinyint(1) DEFAULT '0' COMMENT '三单',
  `type_3s` tinyint(1) DEFAULT '0' COMMENT '三双',
  `type_4d` tinyint(1) DEFAULT '0' COMMENT '四单',
  `type_4s` tinyint(1) DEFAULT '0' COMMENT '四双',
  `codes_hz` int(11) DEFAULT NULL COMMENT '号码和值',
  `code_type` tinyint(1) DEFAULT '4' COMMENT '号码类型:1一字定2二字定3三字定4四字定',
  `created_at` int(11) DEFAULT NULL COMMENT '创建时间',
  `updated_at` int(11) DEFAULT NULL COMMENT '更新时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `code` (`code`),
  KEY `type_22` (`type_22`),
  KEY `type_3` (`type_3`),
  KEY `type_4` (`type_4`),
  KEY `type_3b` (`type_3b`),
  KEY `type_4b` (`type_4b`),
  KEY `type_4ds` (`type_4ds`),
  KEY `code_1` (`code_1`),
  KEY `code_2` (`code_2`),
  KEY `code_3` (`code_3`),
  KEY `code_4` (`code_4`)
) ENGINE=MyISAM AUTO_INCREMENT=14601 DEFAULT CHARSET=utf8 COMMENT='四定号码类型表';

